@Serializable sealed interface OrderEvent
@Serializable @SerialName("order.placed.v1")
data class OrderPlaced(val orderId: String, val occurredAt: Instant) : OrderEvent

private val _events = MutableSharedFlow<OrderEvent>()
val events: SharedFlow<OrderEvent> = _events

suspend fun place(order: Order) { /* commit */ _events.emit(OrderPlaced(order.id, Instant.now())) }

events.filterIsInstance<OrderPlaced>().collect { index.upsert(it.orderId) }
